FUNCTION_BLOCK FB_CopperAnode_CastingWheelSync
VAR_INPUT
    (* Master operational permissives and safety interlocks *)
    bMasterEnable               : BOOL;     (* Master supervisory automatic casting sequence permissive [TRUE=Run, FALSE=Inhibit] *)
    bEStopTripped               : BOOL;     (* Fail-safe safety loop status: active low hardwired circuit [FALSE=Safe/OK, TRUE=E-Stop] *)
    bAckFault                   : BOOL;     (* Operator pushbutton reset / fault acknowledge strobe [rising edge active] *)

    (* Molten copper physical process parameters *)
    rTundishTemp_DegC           : REAL;     (* Tundish molten copper temperature via dual-wavelength optical pyrometer [deg C], range 1080.0-1250.0 *)
    rLadlePourRate_TonHr        : REAL;     (* Instantaneous mass flow rate from tundish ladle scale differentiation [ton/h], range 0.0-140.0 *)
    rAnodeTargetMass_Kg         : REAL;     (* Nominal target finished anode mass per mold [kg], nominal 380.0 to 420.0 *)

    (* Casting wheel kinematics and angular resolution *)
    rWheelSpeed_RPM             : REAL;     (* Measured angular velocity of wheel rim via dual redundant encoder [rpm], range 0.0-5.0 *)
    rWheelPosition_Deg          : REAL;     (* Multi-turn absolute resolver angular coordinate [deg], modulo 360.0 (0.00 to 359.99) *)

    (* Mold wash thermal release spray instrumentation *)
    rMoldTemp_DegC              : REAL;     (* Mold cavity surface temperature at spray wash header pyrometer [deg C], range 100.0-350.0 *)
    rMoldSprayPressure_Bar      : REAL;     (* Mold barite/bone-ash wash slurry manifold supply pressure [bar], nominal 4.5-6.5 *)
    rMoldSprayFlow_Lpm          : REAL;     (* Refractory release agent slurry volumetric flow rate [L/min], nominal 10.0-35.0 *)

    (* Triple Modular Redundancy (2oo3 TMR) Ladle Scale Load Cell Inputs *)
    rTMR_LadleWeight_SensorA_Kg : REAL;     (* Channel A load cell mass transducer under tundish cradle [kg] *)
    rTMR_LadleWeight_SensorB_Kg : REAL;     (* Channel B load cell mass transducer under tundish cradle [kg] *)
    rTMR_LadleWeight_SensorC_Kg : REAL;     (* Channel C load cell mass transducer under tundish cradle [kg] *)

    (* Scan execution cycle timing *)
    rCycleScanDeltaT_Sec        : REAL;     (* PLC cyclical execution task sample interval [s], nominal 0.010 s (10ms) *)
END_VAR

VAR_OUTPUT
    (* Actuation and drive commands *)
    bWheelDriveEnable           : BOOL;     (* Casting wheel servo/hydraulic drive run permissive [TRUE=Drive Run, FALSE=Drive Inhibit] *)
    rWheelSpeedSetpoint_RPM     : REAL;     (* Dynamic angular velocity command to wheel drive inverter [rpm] *)
    rLadleTiltActuator_Pct      : REAL;     (* Proportional electro-hydraulic servo tilt cylinder command [0.0 to 100.0 %] *)
    rSprayPumpSpeed_Pct         : REAL;     (* Variable frequency drive speed demand for slurry release pump [0.0 to 100.0 %] *)
    bMoldSpraySolenoid          : BOOL;     (* High-pressure slurry release atomization nozzle valve trigger [TRUE=Open] *)
    bEmergencyDumpActive        : BOOL;     (* Emergency diverter gate dump solenoid to redirect molten stream to scrap box [TRUE=Dump] *)

    (* Real-time metallurgical process telemetry *)
    rCurrentAnodeMass_Kg        : REAL;     (* Real-time cumulative poured copper net mass in active mold pocket [kg] *)
    bCycleComplete              : BOOL;     (* Single mold pour, fill, settle, and spray coating index complete pulse *)

    (* Supervisory status and fault words *)
    wSystemStatusWord           : WORD;     (* Packed bitfield: B0=Ready, B1=Aligning, B2=Spraying, B3=Pouring, B4=Taper, B5=Degraded *)
    wAlarmCodeWord              : WORD;     (* Diagnostic alarm register: B0=EStop, B1=TempOOR, B2=TMRFault, B3=MassOOR, B4=SprayFail *)
END_VAR

VAR
    (* 2oo3 Triple Modular Redundant Voting Engine Internals *)
    rVotedLadleWeight_Kg        : REAL := 0.0;  (* Arbitrated median weight output from 2oo3 algorithm [kg] *)
    bSensorAFault               : BOOL := FALSE;(* Channel A divergence or open-circuit health flag *)
    bSensorBFault               : BOOL := FALSE;(* Channel B divergence or open-circuit health flag *)
    bSensorCFault               : BOOL := FALSE;(* Channel C divergence or open-circuit health flag *)
    rDevAB                      : REAL := 0.0;  (* Absolute channel A vs B load cell discrepancy [kg] *)
    rDevBC                      : REAL := 0.0;  (* Absolute channel B vs C load cell discrepancy [kg] *)
    rDevCA                      : REAL := 0.0;  (* Absolute channel C vs A load cell discrepancy [kg] *)
    rTMR_Threshold_Kg           : REAL := 12.5; (* Permissible channel divergence threshold before isolation [kg] *)
    iHealthySensorCount         : INT := 3;     (* Count of functioning load cell channels in TMR ensemble *)

    (* First-order PT1 low-pass filter accumulator for noise suppression on hydraulic tilt vibration *)
    rFilteredLadleWeight_Kg     : REAL := 0.0;
    rFilterWeightAlpha          : REAL := 0.22; (* Filter smoothing weight coefficient [0.0 - 1.0] *)
    rPrevFilteredWeight_Kg      : REAL := 0.0;

    (* State-Space Dynamic Observer and Model Predictive Feedforward Matrices *)
    (* State vector: x1 = poured mass [kg], x2 = ladle outflow rate [kg/s], x3 = mold meniscus level [mm] *)
    (* Control input vector: u1 = tilt percentage [%], u2 = wheel speed [rpm] *)
    rState_x1_Mass              : REAL := 0.0;
    rState_x2_Flow              : REAL := 0.0;
    rState_x3_Meniscus          : REAL := 0.0;

    (* System dynamics matrices (discrete A, B parameters for continuous copper casting wheel, Ts=10ms) *)
    rA11 : REAL := 1.0;  rA12 : REAL := 0.010; rA13 : REAL := 0.0;
    rA21 : REAL := 0.0;  rA22 : REAL := 0.880; rA23 : REAL := 0.0;
    rA31 : REAL := 0.0;  rA32 : REAL := 0.045; rA33 : REAL := 0.920;

    rB11 : REAL := 0.0;   rB12 : REAL := 0.0;
    rB21 : REAL := 0.420; rB22 : REAL := -0.050;
    rB31 : REAL := 0.015; rB32 : REAL := 0.180;

    (* Observer correction gains (Luenberger synthesis for molten copper hydrodynamics) *)
    rObsGain_L11                : REAL := 0.320;
    rObsGain_L21                : REAL := 0.540;
    rObsGain_L31                : REAL := 0.160;

    (* Model Predictive / Dynamic Feedforward Controller Variables *)
    rFlowSetpoint_KgSec         : REAL := 0.0;
    rFlowError_KgSec            : REAL := 0.0;
    rMPC_IntegralAccum          : REAL := 0.0;
    rMPC_LastError              : REAL := 0.0;
    rMPC_Kp                     : REAL := 1.15;
    rMPC_Ki                     : REAL := 0.28;
    rMPC_Kd                     : REAL := 0.04;
    rFeedforwardTilt_Pct        : REAL := 0.0;

    (* Thermal Spray Release Recipe Profiler Variables *)
    rSprayTargetPressure_Bar    : REAL := 5.20; (* Reference pressure for optimal slurry droplet Sauter mean diameter [bar] *)
    rSprayBaseDuration_Sec      : REAL := 3.20; (* Nominal wash spray duration on clean mold [s] *)
    rSprayTempCorrection_Sec    : REAL := 0.0;  (* Thermal compensation time delta based on mold surface pyrometer [s] *)
    rSprayComputedDuration_Sec  : REAL := 3.20;
    rSprayElapsed_Sec           : REAL := 0.0;
    rSprayFlowIntegrator_Liters : REAL := 0.0;

    (* Finite State Machine Operational Registers *)
    iOperationState             : INT := 0;     (* Primary FSM state variable: 0=IDLE, 10=TMR_ZERO, 20=MOLD_ALIGN, 30=SPRAY, 40=STANDBY, 50=POUR_MAIN, 60=LUG_TAPER, 70=CUTOFF_SETTLE, 80=INDEX_NEXT, 90=DEGRADED, 99=EMERGENCY *)
    iPrevOperationState         : INT := 0;
    rMoldInitialLadleMass_Kg    : REAL := 0.0;
    rLugTaperThreshold_Kg       : REAL := 350.0;(* Mass setpoint where flow ramps down for lug cavity anti-splash formation *)
    rStreamCutoffLead_Kg        : REAL := 7.80; (* In-flight molten stream mass compensation offset [kg] *)
    rCurrentCavityTarget_Kg     : REAL := 400.0;
    rRemainingFillMass_Kg       : REAL := 0.0;

    (* Watchdogs and auxiliary timers *)
    rStateTimer_Sec             : REAL := 0.0;
    rIndexSettleTimer_Sec       : REAL := 0.0;
    rPourWatchdogMax_Sec        : REAL := 35.0; (* Safety timeout for molten pour per mold *)

    (* Production statistics *)
    diTotalAnodesPoured         : DINT := 0;
    iCurrentMoldPocketIndex     : INT := 1;
    rWheelTargetPosition_Deg    : REAL := 0.0;
    rWheelPositionError_Deg     : REAL := 0.0;
END_VAR

(* ========================================================================= *)
(* CRITICAL SAFETY INTERLOCK & EMERGENCY STOP SUPERVISORY CHECK              *)
(* ========================================================================= *)
IF bEStopTripped THEN
    (* Immediate fail-safe lockdown: isolate hydraulic actuators, engage mechanical friction brakes *)
    bWheelDriveEnable       := FALSE;
    rWheelSpeedSetpoint_RPM := 0.0;
    rLadleTiltActuator_Pct  := 0.0;    (* Gravity fail-safe returns ladle to upright safe attitude *)
    bMoldSpraySolenoid      := FALSE;
    rSprayPumpSpeed_Pct     := 0.0;
    bEmergencyDumpActive    := TRUE;   (* Energize diverter chute to clear tundish nozzle into emergency slag pit *)
    iOperationState         := 99;     (* Force Emergency Stop State *)
    wAlarmCodeWord          := wAlarmCodeWord OR 16#0001; (* Set Alarm Bit 0: Hardwired E-Stop Triggered *)
    wSystemStatusWord       := 16#0000;
    RETURN;
END_IF;

(* Fault acknowledge unlatch *)
IF bAckFault THEN
    wAlarmCodeWord := 16#0000;
    IF iOperationState = 99 THEN
        iOperationState := 0; (* Return to Idle upon manual acknowledge *)
    END_IF;
END_IF;

(* Delta-time clamp to avoid numerical divergence during PLC task jitter *)
IF rCycleScanDeltaT_Sec <= 0.001 OR rCycleScanDeltaT_Sec > 0.100 THEN
    rCycleScanDeltaT_Sec := 0.010; (* Default to nominal 10 ms *)
END_IF;

(* ========================================================================= *)
(* 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) LOAD CELL VOTING ALGORITHM           *)
(* ========================================================================= *)
rDevAB := ABS(rTMR_LadleWeight_SensorA_Kg - rTMR_LadleWeight_SensorB_Kg);
rDevBC := ABS(rTMR_LadleWeight_SensorB_Kg - rTMR_LadleWeight_SensorC_Kg);
rDevCA := ABS(rTMR_LadleWeight_SensorC_Kg - rTMR_LadleWeight_SensorA_Kg);

bSensorAFault := (rDevAB > rTMR_Threshold_Kg) AND (rDevCA > rTMR_Threshold_Kg);
bSensorBFault := (rDevAB > rTMR_Threshold_Kg) AND (rDevBC > rTMR_Threshold_Kg);
bSensorCFault := (rDevBC > rTMR_Threshold_Kg) AND (rDevCA > rTMR_Threshold_Kg);

(* Count healthy sensor transducers *)
iHealthySensorCount := 3;
IF bSensorAFault THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;
IF bSensorBFault THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;
IF bSensorCFault THEN iHealthySensorCount := iHealthySensorCount - 1; END_IF;

(* Select arbitration strategy based on health quorum *)
IF iHealthySensorCount = 3 THEN
    (* Full 2oo3 median arbitration *)
    IF (rTMR_LadleWeight_SensorA_Kg >= rTMR_LadleWeight_SensorB_Kg AND rTMR_LadleWeight_SensorA_Kg <= rTMR_LadleWeight_SensorC_Kg) OR
       (rTMR_LadleWeight_SensorA_Kg <= rTMR_LadleWeight_SensorB_Kg AND rTMR_LadleWeight_SensorA_Kg >= rTMR_LadleWeight_SensorC_Kg) THEN
        rVotedLadleWeight_Kg := rTMR_LadleWeight_SensorA_Kg;
    ELSIF (rTMR_LadleWeight_SensorB_Kg >= rTMR_LadleWeight_SensorA_Kg AND rTMR_LadleWeight_SensorB_Kg <= rTMR_LadleWeight_SensorC_Kg) OR
          (rTMR_LadleWeight_SensorB_Kg <= rTMR_LadleWeight_SensorA_Kg AND rTMR_LadleWeight_SensorB_Kg >= rTMR_LadleWeight_SensorC_Kg) THEN
        rVotedLadleWeight_Kg := rTMR_LadleWeight_SensorB_Kg;
    ELSE
        rVotedLadleWeight_Kg := rTMR_LadleWeight_SensorC_Kg;
    END_IF;
ELSIF iHealthySensorCount = 2 THEN
    (* 1oo2 Graceful degradation: average the two surviving healthy channels *)
    wAlarmCodeWord := wAlarmCodeWord OR 16#0004; (* Alarm Bit 2: TMR Single Channel Discrepancy *)
    IF bSensorAFault THEN
        rVotedLadleWeight_Kg := (rTMR_LadleWeight_SensorB_Kg + rTMR_LadleWeight_SensorC_Kg) * 0.5;
    ELSIF bSensorBFault THEN
        rVotedLadleWeight_Kg := (rTMR_LadleWeight_SensorA_Kg + rTMR_LadleWeight_SensorC_Kg) * 0.5;
    ELSE
        rVotedLadleWeight_Kg := (rTMR_LadleWeight_SensorA_Kg + rTMR_LadleWeight_SensorB_Kg) * 0.5;
    END_IF;
ELSE
    (* Critical TMR failure: enter fallback mode using differentiated volumetric model *)
    wAlarmCodeWord := wAlarmCodeWord OR 16#0008; (* Alarm Bit 3: Critical TMR Quorum Lost *)
    IF iOperationState >= 50 AND iOperationState <= 70 THEN
        iOperationState := 90; (* Divert to graceful degradation finish *)
    END_IF;
    rVotedLadleWeight_Kg := rPrevFilteredWeight_Kg - (rState_x2_Flow * rCycleScanDeltaT_Sec);
END_IF;

(* Discrete PT1 First-Order Low-Pass Filter on Voted Ladle Weight *)
rFilteredLadleWeight_Kg := (rFilterWeightAlpha * rVotedLadleWeight_Kg) + ((1.0 - rFilterWeightAlpha) * rPrevFilteredWeight_Kg);
rPrevFilteredWeight_Kg  := rFilteredLadleWeight_Kg;

(* Calculate net poured mass in active mold pocket *)
IF iOperationState >= 40 AND iOperationState <= 75 THEN
    rCurrentAnodeMass_Kg := rMoldInitialLadleMass_Kg - rFilteredLadleWeight_Kg;
    IF rCurrentAnodeMass_Kg < 0.0 THEN
        rCurrentAnodeMass_Kg := 0.0;
    END_IF;
ELSE
    rCurrentAnodeMass_Kg := 0.0;
END_IF;

(* ========================================================================= *)
(* STATE-SPACE LUENBERGER OBSERVER FOR HYDRODYNAMIC MENISCUS DYNAMICS       *)
(* ========================================================================= *)
(* Compute state predictions based on A and B plant matrices *)
rState_x1_Mass := (rA11 * rState_x1_Mass) + (rA12 * rState_x2_Flow) + (rA13 * rState_x3_Meniscus) +
                  (rB11 * rLadleTiltActuator_Pct) + (rB12 * rWheelSpeed_RPM);

rState_x2_Flow := (rA21 * rState_x1_Mass) + (rA22 * rState_x2_Flow) + (rA23 * rState_x3_Meniscus) +
                  (rB21 * rLadleTiltActuator_Pct) + (rB22 * rWheelSpeed_RPM);

rState_x3_Meniscus := (rA31 * rState_x1_Mass) + (rA32 * rState_x2_Flow) + (rA33 * rState_x3_Meniscus) +
                      (rB31 * rLadleTiltActuator_Pct) + (rB32 * rWheelSpeed_RPM);

(* Measurement innovation injection using actual filtered mass reading *)
rState_x1_Mass := rState_x1_Mass + (rObsGain_L11 * (rCurrentAnodeMass_Kg - rState_x1_Mass));
rState_x2_Flow := rState_x2_Flow + (rObsGain_L21 * (rCurrentAnodeMass_Kg - rState_x1_Mass));
rState_x3_Meniscus := rState_x3_Meniscus + (rObsGain_L31 * (rCurrentAnodeMass_Kg - rState_x1_Mass));

(* Boundary clamping on observer states *)
IF rState_x1_Mass < 0.0 THEN rState_x1_Mass := 0.0; END_IF;
IF rState_x2_Flow < 0.0 THEN rState_x2_Flow := 0.0; END_IF;
IF rState_x3_Meniscus < 0.0 THEN rState_x3_Meniscus := 0.0; END_IF;

(* Process pyrometer thermal limits validation *)
IF rTundishTemp_DegC < 1120.0 OR rTundishTemp_DegC > 1240.0 THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0002; (* Alarm Bit 1: Tundish Superheat Temperature Out of Range *)
END_IF;

IF rMoldTemp_DegC > 310.0 THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0020; (* Alarm Bit 5: Mold Over-Temperature Risk of Welding *)
END_IF;

(* ========================================================================= *)
(* MULTI-STAGE FINITE STATE MACHINE (FSM) SEQUENCE ENGINE                    *)
(* ========================================================================= *)
CASE iOperationState OF

    0: (* ------------------- IDLE / SYSTEM STANDBY ----------------------- *)
        bWheelDriveEnable           := FALSE;
        rWheelSpeedSetpoint_RPM     := 0.0;
        rLadleTiltActuator_Pct      := 0.0;
        bMoldSpraySolenoid          := FALSE;
        rSprayPumpSpeed_Pct         := 0.0;
        bEmergencyDumpActive        := FALSE;
        bCycleComplete              := FALSE;
        rStateTimer_Sec             := 0.0;
        rMPC_IntegralAccum          := 0.0;
        rMPC_LastError              := 0.0;

        wSystemStatusWord := 16#0001; (* Status Bit 0: System Idle / Ready *)

        IF bMasterEnable AND (wAlarmCodeWord = 16#0000) THEN
            iOperationState := 10; (* Proceed to Calibration & Zero Tare *)
        END_IF;

    10: (* ------------------ TMR ZERO CALIBRATION & INITIALIZATION -------- *)
        wSystemStatusWord := 16#0002; (* Status Bit 1: Tare & Verification *)
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;

        (* Check load cell stability for 1.5 seconds before latching mold start weight *)
        IF rStateTimer_Sec >= 1.50 THEN
            rMoldInitialLadleMass_Kg := rFilteredLadleWeight_Kg;
            rState_x1_Mass           := 0.0;
            rState_x2_Flow           := 0.0;
            rState_x3_Meniscus       := 0.0;
            rStateTimer_Sec          := 0.0;
            iOperationState          := 20; (* Advance to Wheel Index Alignment *)
        END_IF;

    20: (* ------------------ MOLD CAROUSEL INDEX ALIGNMENT --------------- *)
        wSystemStatusWord := 16#0004; (* Status Bit 2: Wheel Aligning *)
        bWheelDriveEnable := TRUE;

        (* Target angular coordinate for current mold pocket (16-mold wheel = 22.5 deg per sector) *)
        rWheelTargetPosition_Deg := DINT_TO_REAL(iCurrentMoldPocketIndex - 1) * 22.50;
        rWheelPositionError_Deg  := rWheelTargetPosition_Deg - rWheelPosition_Deg;

        (* Normalize error within [-180.0, 180.0] *)
        WHILE rWheelPositionError_Deg > 180.0 DO
            rWheelPositionError_Deg := rWheelPositionError_Deg - 360.0;
        END_WHILE;
        WHILE rWheelPositionError_Deg < -180.0 DO
            rWheelPositionError_Deg := rWheelPositionError_Deg + 360.0;
        END_WHILE;

        (* Precision closed-loop proportional positioning *)
        IF ABS(rWheelPositionError_Deg) > 0.08 THEN
            rWheelSpeedSetpoint_RPM := rWheelPositionError_Deg * 0.45;
            (* Slew rate and ceiling limit *)
            IF rWheelSpeedSetpoint_RPM > 2.20 THEN rWheelSpeedSetpoint_RPM := 2.20; END_IF;
            IF rWheelSpeedSetpoint_RPM < -2.20 THEN rWheelSpeedSetpoint_RPM := -2.20; END_IF;
            rIndexSettleTimer_Sec := 0.0;
        ELSE
            (* Pocket aligned within deadband: hold position and settle *)
            rWheelSpeedSetpoint_RPM := 0.0;
            rIndexSettleTimer_Sec := rIndexSettleTimer_Sec + rCycleScanDeltaT_Sec;
            IF rIndexSettleTimer_Sec >= 0.80 THEN
                rStateTimer_Sec := 0.0;
                iOperationState := 30; (* Proceed to Mold Thermal Spray Release *)
            END_IF;
        END_IF;

    30: (* ------------------ MOLD THERMAL RELEASE WASH SPRAY ------------- *)
        wSystemStatusWord := 16#0008; (* Status Bit 3: Thermal Spray Coating *)
        rWheelSpeedSetpoint_RPM := 0.0;

        (* Dynamic thermal compensation: at higher mold temps, spray must be adjusted to prevent flash-boiling *)
        rSprayTempCorrection_Sec := (rMoldTemp_DegC - 180.0) * 0.008;
        IF rSprayTempCorrection_Sec < -0.60 THEN rSprayTempCorrection_Sec := -0.60; END_IF;
        IF rSprayTempCorrection_Sec > 1.20  THEN rSprayTempCorrection_Sec := 1.20;  END_IF;
        rSprayComputedDuration_Sec := rSprayBaseDuration_Sec + rSprayTempCorrection_Sec;

        (* Modulate slurry delivery pump VFD and open atomization header valve *)
        rSprayPumpSpeed_Pct := 75.0 + ((rSprayTargetPressure_Bar - rMoldSprayPressure_Bar) * 8.5);
        IF rSprayPumpSpeed_Pct > 100.0 THEN rSprayPumpSpeed_Pct := 100.0; END_IF;
        IF rSprayPumpSpeed_Pct < 30.0  THEN rSprayPumpSpeed_Pct := 30.0;  END_IF;

        bMoldSpraySolenoid := TRUE;
        rSprayElapsed_Sec := rSprayElapsed_Sec + rCycleScanDeltaT_Sec;
        rSprayFlowIntegrator_Liters := rSprayFlowIntegrator_Liters + (rMoldSprayFlow_Lpm / 60.0 * rCycleScanDeltaT_Sec);

        (* Verify atomization pressure envelope *)
        IF rSprayElapsed_Sec > 0.80 AND rMoldSprayPressure_Bar < 3.80 THEN
            wAlarmCodeWord := wAlarmCodeWord OR 16#0010; (* Alarm Bit 4: Spray Atomization Low Pressure *)
        END_IF;

        IF rSprayElapsed_Sec >= rSprayComputedDuration_Sec THEN
            bMoldSpraySolenoid := FALSE;
            rSprayPumpSpeed_Pct := 0.0;
            rSprayElapsed_Sec   := 0.0;
            rStateTimer_Sec     := 0.0;
            iOperationState     := 40; (* Proceed to Tundish Approach Standby *)
        END_IF;

    40: (* ------------------ TUNDISH APPROACH & NOZZLE DWELL ------------- *)
        wSystemStatusWord := 16#0010; (* Status Bit 4: Tundish Approach *)
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;

        (* Rapid pre-tilt to standby meniscus verge angle (approx 28.5% actuator stroke) *)
        rLadleTiltActuator_Pct := 28.5;
        rWheelSpeedSetpoint_RPM := 0.0;

        IF rStateTimer_Sec >= 1.20 THEN
            rStateTimer_Sec := 0.0;
            rMoldInitialLadleMass_Kg := rFilteredLadleWeight_Kg;
            rLugTaperThreshold_Kg    := rAnodeTargetMass_Kg - 45.0; (* Taper last 45 kg *)
            rCurrentCavityTarget_Kg  := rAnodeTargetMass_Kg;
            iOperationState          := 50; (* Transition to Main Synchronized Pour *)
        END_IF;

    50: (* ------------------ MAIN BODY SYNCHRONIZED HIGH-FLOW POUR ------- *)
        wSystemStatusWord := 16#0020; (* Status Bit 5: Main Body Pouring *)
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;

        (* Safety watchdog *)
        IF rStateTimer_Sec > rPourWatchdogMax_Sec THEN
            wAlarmCodeWord := wAlarmCodeWord OR 16#0080; (* Alarm Bit 7: Pour Cycle Watchdog Exceeded *)
            iOperationState := 99; (* Abort to emergency safe position *)
        END_IF;

        (* Optimal bulk flow rate setpoint = 26.5 kg/s (~95.4 ton/h) *)
        rFlowSetpoint_KgSec := 26.50;

        (* Model Predictive Control & Dynamic Feedforward Synthesis *)
        rFlowError_KgSec   := rFlowSetpoint_KgSec - rState_x2_Flow;
        rMPC_IntegralAccum := rMPC_IntegralAccum + (rFlowError_KgSec * rCycleScanDeltaT_Sec);
        IF rMPC_IntegralAccum > 30.0  THEN rMPC_IntegralAccum := 30.0;  END_IF;
        IF rMPC_IntegralAccum < -10.0 THEN rMPC_IntegralAccum := -10.0; END_IF;

        rFeedforwardTilt_Pct := 32.0 + (rState_x1_Mass * 0.035); (* Adaptive tundish head depletion compensation *)
        rLadleTiltActuator_Pct := rFeedforwardTilt_Pct + (rMPC_Kp * rFlowError_KgSec) +
                                  (rMPC_Ki * rMPC_IntegralAccum) +
                                  (rMPC_Kd * (rFlowError_KgSec - rMPC_LastError) / rCycleScanDeltaT_Sec);
        rMPC_LastError := rFlowError_KgSec;

        (* Clamp tilt actuator safe operating authority *)
        IF rLadleTiltActuator_Pct > 85.0 THEN rLadleTiltActuator_Pct := 85.0; END_IF;
        IF rLadleTiltActuator_Pct < 15.0 THEN rLadleTiltActuator_Pct := 15.0; END_IF;

        (* Wheel synchronized micro-oscillation: prevents meniscus liquid pooling and ensures uniform flat anode sheet *)
        rWheelSpeedSetpoint_RPM := 0.080 * SIN(rStateTimer_Sec * 3.14159);

        (* Check for lug taper transition threshold *)
        IF rCurrentAnodeMass_Kg >= rLugTaperThreshold_Kg THEN
            iOperationState := 60; (* Transition to Lug Formation Taper *)
        END_IF;

    60: (* ------------------ LUG FORMATION FLOW TAPER & MENISCUS DAMPING - *)
        wSystemStatusWord := 16#0040; (* Status Bit 6: Lug Cavity Tapering *)
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;

        (* Remaining mass to pour before in-flight stream cutoff *)
        rRemainingFillMass_Kg := (rCurrentCavityTarget_Kg - rStreamCutoffLead_Kg) - rCurrentAnodeMass_Kg;

        (* Progressively ramp down flow rate to 6.0 kg/s to avoid lug flashing *)
        rFlowSetpoint_KgSec := 6.0 + (rRemainingFillMass_Kg * 0.40);
        IF rFlowSetpoint_KgSec > 16.0 THEN rFlowSetpoint_KgSec := 16.0; END_IF;
        IF rFlowSetpoint_KgSec < 4.5  THEN rFlowSetpoint_KgSec := 4.5;  END_IF;

        (* Damp wheel velocity to zero for pristine lug corner crystallization *)
        rWheelSpeedSetpoint_RPM := 0.0;

        (* Tilt control during taper *)
        rFlowError_KgSec := rFlowSetpoint_KgSec - rState_x2_Flow;
        rLadleTiltActuator_Pct := 28.0 + (rRemainingFillMass_Kg * 0.18) + (rMPC_Kp * rFlowError_KgSec);
        IF rLadleTiltActuator_Pct > 60.0 THEN rLadleTiltActuator_Pct := 60.0; END_IF;
        IF rLadleTiltActuator_Pct < 10.0 THEN rLadleTiltActuator_Pct := 10.0; END_IF;

        (* Cutoff condition incorporating in-flight molten metal trajectory *)
        IF rCurrentAnodeMass_Kg >= (rCurrentCavityTarget_Kg - rStreamCutoffLead_Kg) THEN
            rLadleTiltActuator_Pct := 0.0; (* Immediate back-tilt to break pour meniscus *)
            rStateTimer_Sec        := 0.0;
            iOperationState        := 70;  (* Transition to Stream Cutoff & Settling *)
        END_IF;

    70: (* ------------------ STREAM CUTOFF & SOLIDIFICATION SETTLE ------- *)
        wSystemStatusWord := 16#0080; (* Status Bit 7: Settling & Solidification *)
        rLadleTiltActuator_Pct  := 0.0;
        rWheelSpeedSetpoint_RPM := 0.0;
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;

        (* Dwell 2.5 seconds for molten metal in-flight capture and crust inception *)
        IF rStateTimer_Sec >= 2.50 THEN
            (* Final anode mass tolerance audit (nominal +/- 1.5%) *)
            IF ABS(rCurrentAnodeMass_Kg - rCurrentCavityTarget_Kg) > (rCurrentCavityTarget_Kg * 0.015) THEN
                wAlarmCodeWord := wAlarmCodeWord OR 16#0040; (* Alarm Bit 6: Anode Mass Tolerance Warning *)
            END_IF;

            diTotalAnodesPoured := diTotalAnodesPoured + 1;
            bCycleComplete := TRUE;
            rStateTimer_Sec := 0.0;
            iOperationState := 80; (* Proceed to Index Carousel *)
        END_IF;

    80: (* ------------------ WHEEL INDEX ADVANCE TO NEXT POCKET --------- *)
        wSystemStatusWord := 16#0100; (* Status Bit 8: Carousel Indexing *)
        bCycleComplete := FALSE;

        (* Increment wheel pocket modulo 16 *)
        iCurrentMoldPocketIndex := iCurrentMoldPocketIndex + 1;
        IF iCurrentMoldPocketIndex > 16 THEN
            iCurrentMoldPocketIndex := 1;
        END_IF;

        (* Check continuous casting permissive *)
        IF bMasterEnable AND (wAlarmCodeWord = 16#0000) THEN
            iOperationState := 20; (* Align next mold pocket *)
        ELSE
            iOperationState := 0;  (* Return to Idle standby *)
        END_IF;

    90: (* ------------------ GRACEFUL DEGRADATION FINISH ----------------- *)
        wSystemStatusWord := 16#0200; (* Status Bit 9: Graceful Limp-Home Mode *)
        (* Load cell failure fallback: finish current pour via calibrated open-loop timed tilt profile *)
        rStateTimer_Sec := rStateTimer_Sec + rCycleScanDeltaT_Sec;
        rWheelSpeedSetpoint_RPM := 0.0;

        IF rStateTimer_Sec < 4.0 THEN
            rLadleTiltActuator_Pct := 26.0; (* Controlled low-flow drain *)
        ELSE
            rLadleTiltActuator_Pct := 0.0;
            IF rStateTimer_Sec >= 6.5 THEN
                iOperationState := 0; (* Force Stop after clearing cavity *)
            END_IF;
        END_IF;

    99: (* ------------------ EMERGENCY SAFE DUMP ------------------------ *)
        wSystemStatusWord := 16#8000; (* Status Bit 15: Emergency Dump Activated *)
        bWheelDriveEnable       := FALSE;
        rWheelSpeedSetpoint_RPM := 0.0;
        rLadleTiltActuator_Pct  := 0.0;
        bMoldSpraySolenoid      := FALSE;
        rSprayPumpSpeed_Pct     := 0.0;
        bEmergencyDumpActive    := TRUE;

        (* Hold dump chute until manual acknowledge clears alarm *)
        IF NOT bEStopTripped AND bAckFault THEN
            bEmergencyDumpActive := FALSE;
            iOperationState      := 0;
        END_IF;

END_CASE;

